<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute,useRouter}from'vue-router';import InventorySubnav from '../components/InventorySubnav.vue';import{useInventoryStore}from'../runtime/inventory-store';import type{LocationDraft}from'../types';import'./inventory-views.css';const route=useRoute();const router=useRouter();const store=useInventoryStore();const{workspace,saving}=storeToRefs(store);const id=computed(()=>typeof route.params.locationId==='string'?route.params.locationId:undefined);const form=reactive<LocationDraft>({warehouseId:String(route.query.warehouseId??''),code:'',name:'',status:'enabled',note:null});const error=ref('');onMounted(async()=>{await store.load();const value=workspace.value.locations.find(x=>x.id===id.value);if(value)Object.assign(form,value)});async function submit(){error.value='';try{await store.saveLocation({...form},id.value);await router.push('/inventory/locations')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}
</script>
<template><section class="inventory-page"><header class="inventory-header"><div><RouterLink to="/inventory/locations">← 返回库位列表</RouterLink><h1>{{id?'编辑库位':'新增库位'}}</h1><p>编码和名称在仓内唯一；非零库存时不能禁用或更换仓库。</p></div></header><InventorySubnav/><form class="inventory-panel inventory-form" @submit.prevent="submit"><label>所属仓库<select v-model="form.warehouseId" required><option value="" disabled>请选择</option><option v-for="x in workspace.warehouses.filter(w=>w.status==='enabled')" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>状态<select v-model="form.status"><option value="enabled">启用</option><option value="disabled">禁用</option></select></label><label>库位编码<input v-model="form.code" maxlength="40" required></label><label>库位名称<input v-model="form.name" maxlength="40" required></label><label class="wide">备注<textarea v-model="form.note" maxlength="500" rows="4"></textarea></label><p v-if="error" class="wide inventory-warning">{{error}}</p><div class="inventory-form-actions"><RouterLink class="inv-button" to="/inventory/locations">取消</RouterLink><button class="inv-button primary" :disabled="saving">{{saving?'保存中…':'保存'}}</button></div></form></section></template>
